const aluno = {
  nome: 'Ana',
  idade: 15,
  cidade: 'São Paulo'
};

// Passo 2: aninhamos uma lista de objetos — o boletim.
aluno.notas = [
  { materia: 'matemática', valor: 8 },
  { materia: 'português', valor: 7 }
];

